// History of the balance tests: one folder per test in tests/history/ (versioned, unlike temp/).
//   tests/history/<id>/meta.json            date, options, git commit, fingerprints of the data and of the bot, games played
//   tests/history/<id>/<phase>.json|csv     detailed results of each phase (lieutenants, servants, equipment, dungeons)
//   tests/history/<id>/report-<phase>.txt  the text report, as displayed in the terminal
//   tests/history/index.json                summary list of all tests (regenerated by reindex(), never by hand)
'use strict';
const fs = require('fs'), path = require('path'), crypto = require('crypto'), { execFileSync } = require('child_process');
const root = path.join(__dirname, '..');
const historyFolder = path.join(root, 'tests', 'history');

const git = (...a) => { try { return execFileSync('git', a, { cwd: root, encoding: 'utf8', stdio: ['ignore', 'pipe', 'ignore'] }).trim(); } catch (e) { return ''; } };
const fingerprint = files => {
  const h = crypto.createHash('sha1');
  files.forEach(f => h.update(fs.readFileSync(path.join(root, f))));
  return h.digest('hex').slice(0, 10);
};
// Fingerprint of the rules and cards (data.js, engine.js) and of the automatic player: two tests are comparable only if they are equal.
const dataFingerprint = () => fingerprint(['prototype/data.js', 'prototype/engine.js']);
const botFingerprint = () => fingerprint(['tools/player-bot.js', 'tools/load-game.js']);

// Games per combination depending on the scale (see balance.js for the meaning of each number).
const scales = {
  small: { lieutenants: 4, cardList: 1, control: 4, dungeons: 4, extras: 1 },
  normal: { lieutenants: 60, cardList: 3, control: 20, dungeons: 60, extras: 3 },
  massive: { lieutenants: 300, cardList: 6, control: 60, dungeons: 150, extras: 6 }
};

const pad2 = n => String(n).padStart(2, '0');
function nouvelIdentifiant(scale, date = new Date()) {
  const base = `${date.getFullYear()}-${pad2(date.getMonth() + 1)}-${pad2(date.getDate())}-${pad2(date.getHours())}${pad2(date.getMinutes())}-${scale}`;
  let id = base, n = 2;
  while (fs.existsSync(path.join(historyFolder, id))) id = `${base}-${n++}`;
  return id;
}

// Creates the folder of a test and returns { id, folder, meta, save() }.
function createTest(options, { folder = null, date = new Date() } = {}) {
  const id = nouvelIdentifiant(options.scale, date);
  const dir = folder || path.join(historyFolder, id);
  fs.mkdirSync(dir, { recursive: true });
  const modified = git('status', '--porcelain', '--', 'prototype/data.js', 'prototype/engine.js', 'tools/player-bot.js').length > 0;
  const meta = { id, date: date.toISOString(), ...options, phases: {}, commit: git('rev-parse', '--short', 'HEAD'), modified, hashDonnees: dataFingerprint(), hashBot: botFingerprint() };
  const t = { id, folder: dir, meta, save() { fs.writeFileSync(path.join(dir, 'meta.json'), JSON.stringify(meta, null, 1) + '\n'); } };
  t.save();
  return t;
}

// Summary of a test for the index: a few headline figures per phase, to get oriented without opening the files.
function resume(id) {
  const dir = path.join(historyFolder, id);
  const read = f => { try { return JSON.parse(fs.readFileSync(path.join(dir, f), 'utf8')); } catch (e) { return null; } };
  const meta = read('meta.json');
  if (!meta) return null;
  const r = { ...meta, head: {} };
  const L = read('lieutenants.json'), S = read('servants.json'), E = read('equipment.json'), D = read('dungeons.json');
  if (L) r.head.lieutenants = { wins: L.global, strongest: L.lieutenants[0].name, weakest: L.lieutenants[L.lieutenants.length - 1].name };
  if (S) r.head.servants = { control: S.control, tooStrong: S.cardList.filter(c => c.verdict.startsWith('▲')).length, tooWeak: S.cardList.filter(c => c.verdict.startsWith('▼')).length };
  if (E) r.head.equipment = { control: E.control, tooStrong: E.cardList.filter(c => c.verdict.startsWith('▲')).length, tooWeak: E.cardList.filter(c => c.verdict.startsWith('▼')).length };
  if (D) r.head.dungeons = { easiest: D.dungeons.slice().sort((a, b) => b.rate - a.rate)[0].name, hardest: D.dungeons.slice().sort((a, b) => a.rate - b.rate)[0].name };
  return r;
}

// Catalog of the current game (species, archetypes, types and HP of the lieutenants): used by the Test page, which separates species from archetype.
function writeCatalog() {
  const X = require('./load-game').load({ fast: true }).X;
  const lieutenants = Object.fromEntries(Object.entries(X.HEROES).map(([id, h]) => [id, { name: h.name, types: h.types, hp: h.hp }]));
  fs.writeFileSync(path.join(root, 'tests', 'catalog.json'), JSON.stringify({ speciesList: X.SPECIES, archetypes: X.ARCHETYPES, typeNames: X.TYPE_NAMES, lieutenants, names: X.IDENTIFIERS }, null, 1) + '\n');
}

function reindex() {
  fs.mkdirSync(historyFolder, { recursive: true });
  writeCatalog();
  const ids = fs.readdirSync(historyFolder).filter(d => fs.existsSync(path.join(historyFolder, d, 'meta.json'))).sort();
  const tests = ids.map(resume).filter(Boolean).sort((a, b) => b.date.localeCompare(a.date));
  fs.writeFileSync(path.join(historyFolder, 'index.json'), JSON.stringify({ tests }, null, 1) + '\n');
  return tests;
}

module.exports = { scales, historyFolder, createTest, reindex, dataFingerprint, botFingerprint, root };
